import versions from "@/public/bibles/versions.json";

// The versions members can choose. Generated by scripts/build-bibles.mjs —
// add a version there, not here. All are public domain, so all can be
// downloaded for offline reading.

export type BibleVersion = (typeof versions)[number];

export const VERSIONS: readonly BibleVersion[] = versions;

/** The modern-English public-domain version; also what the reader used before v2. */
export const DEFAULT_VERSION_ID = "web";

export function versionById(id: string | null | undefined): BibleVersion {
  return VERSIONS.find((v) => v.id === id) ?? VERSIONS.find((v) => v.id === DEFAULT_VERSION_ID)!;
}
